import {
    _decorator, Component, Node,
    director,
    AudioSource,
} from 'cc';
import { GameState } from '../gameState';
import { SceneName } from '../constants';
import { AudioManager } from '../audioManager';
import { mEmitter } from '../mEmitter';
import { PopupManager } from '../popup/popupManager';
const { ccclass, property } = _decorator;

@ccclass('RootManager')
export class RootManager extends Component {

    @property(AudioSource)
    musicSource: AudioSource;

    @property(AudioSource)
    bgmSource: AudioSource;

    @property(Node)
    popupBackground: Node;

    @property(Node)
    settingPopup: Node;

    @property(Node)
    resultPopup: Node;


    protected onLoad(): void {
        new mEmitter();
        new GameState();
        GameState.instance.root = this.node;

        new AudioManager();
        AudioManager.instance.bgmSource = this.bgmSource;
        AudioManager.instance.sfxSource = this.musicSource;

        new PopupManager();
        PopupManager.instance.background = this.popupBackground;
        PopupManager.instance.settingPopup = this.settingPopup;
        PopupManager.instance.resultPopup = this.resultPopup;
    }

    protected start(): void {

        director.addPersistRootNode(this.node);
        director.loadScene(SceneName.LOADING);
    }

    protected update(dt: number): void {
        if (GameState.instance.music){
            this.bgmSource.volume = 1;
        }
        else {
            this.bgmSource.volume = 0;
        }
    }

}

